pub(crate) fn open_walk_held(ty: &Ty) -> Option<Ty> {
    match ty {
        Ty::Seq { item, .. } => {
            let item = nikaia_std::boxed::open(item);
            return Some(item.clone());
        },
        Ty::Named { args, .. } => { if args.len() == 1 { return Some((*nikaia_std::index::get(&args, 0)).clone()); } },
        _ => { },
    }
    None
}

